import{_ as t,o as a,c as d,a2 as s}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Lifecycle","description":"The 12 states a commitment moves through from detection to resolution.","frontmatter":{"title":"Lifecycle","description":"The 12 states a commitment moves through from detection to resolution."},"headers":[],"relativePath":"core-concepts/lifecycle.md","filePath":"core-concepts/lifecycle.md"}'),n={name:"core-concepts/lifecycle.md"};function i(o,e,c,l,r,p){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h1><p>Every commitment starts at <code>DETECTED</code> and moves through states based on elapsed time and evidence submitted. COGEXT manages all time-based transitions automatically.</p><h2 id="state-diagram" tabindex="-1">State diagram <a class="header-anchor" href="#state-diagram" aria-label="Permalink to &quot;State diagram&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─────────────────────────────┐</span></span>
<span class="line"><span>                    ▼                             │</span></span>
<span class="line"><span>DETECTED → PENDING_REVIEW → OPEN → DUE → OVERDUE │</span></span>
<span class="line"><span>                              │        │          │</span></span>
<span class="line"><span>                              └────────┴──────────┤</span></span>
<span class="line"><span>                                                  ▼</span></span>
<span class="line"><span>                              FULFILLED / FAILED / CONTRADICTED</span></span>
<span class="line"><span>                              CANCELLED / SUPERSEDED / BLOCKED / EXPIRED</span></span></code></pre></div><h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th></tr></thead><tbody><tr><td><code>DETECTED</code></td><td>Just extracted from text — not yet validated</td></tr><tr><td><code>PENDING_REVIEW</code></td><td>Flagged for human review before activation (low confidence or policy rule)</td></tr><tr><td><code>OPEN</code></td><td>Active — deadline is in the future</td></tr><tr><td><code>DUE</code></td><td>Deadline has been reached, awaiting fulfillment signal</td></tr><tr><td><code>OVERDUE</code></td><td>Past deadline with no fulfillment evidence</td></tr><tr><td><code>FULFILLED</code></td><td>Evidence confirms the commitment was met</td></tr><tr><td><code>FAILED</code></td><td>Commitment was not met — evidence of failure or explicit update</td></tr><tr><td><code>CONTRADICTED</code></td><td>Prior fulfillment claim contradicted by new evidence</td></tr><tr><td><code>CANCELLED</code></td><td>Explicitly cancelled by the commitment maker</td></tr><tr><td><code>SUPERSEDED</code></td><td>Replaced by a newer commitment (e.g. deadline moved)</td></tr><tr><td><code>BLOCKED</code></td><td>Cannot proceed — external dependency unresolved</td></tr><tr><td><code>EXPIRED</code></td><td>Timed out with no resolution after the overdue window</td></tr></tbody></table><h2 id="transitions" tabindex="-1">Transitions <a class="header-anchor" href="#transitions" aria-label="Permalink to &quot;Transitions&quot;">​</a></h2><h3 id="time-based-automatic" tabindex="-1">Time-based (automatic) <a class="header-anchor" href="#time-based-automatic" aria-label="Permalink to &quot;Time-based (automatic)&quot;">​</a></h3><p>COGEXT advances these transitions on a schedule:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OPEN ──(deadline reached)──► DUE</span></span>
<span class="line"><span>DUE  ──(grace period ends)──► OVERDUE</span></span>
<span class="line"><span>OVERDUE ──(expiry window)──► EXPIRED</span></span></code></pre></div><h3 id="evidence-based" tabindex="-1">Evidence-based <a class="header-anchor" href="#evidence-based" aria-label="Permalink to &quot;Evidence-based&quot;">​</a></h3><p>Submitting evidence via the <code>/evidence</code> endpoint triggers:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OPEN / DUE / OVERDUE + fulfillment evidence  ──► FULFILLED</span></span>
<span class="line"><span>OPEN / DUE / OVERDUE + contradiction evidence ──► FAILED</span></span>
<span class="line"><span>FULFILLED + contradiction evidence            ──► CONTRADICTED</span></span></code></pre></div><h3 id="manual" tabindex="-1">Manual <a class="header-anchor" href="#manual" aria-label="Permalink to &quot;Manual&quot;">​</a></h3><p>Use the <a href="/api-reference/update-state.html">Update State</a> endpoint to force any valid transition:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Cancel a commitment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /commitments/cmt_abc123/state</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;state&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;CANCELLED&quot;,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;reason&quot;:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Project deprioritised.&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> }</span></span></code></pre></div><p>Valid manual targets: <code>OPEN</code>, <code>FULFILLED</code>, <code>FAILED</code>, <code>CANCELLED</code>, <code>BLOCKED</code>, <code>SUPERSEDED</code></p><h2 id="webhook-events" tabindex="-1">Webhook events <a class="header-anchor" href="#webhook-events" aria-label="Permalink to &quot;Webhook events&quot;">​</a></h2><p>Every state transition fires a webhook event:</p><table tabindex="0"><thead><tr><th>Event</th><th>Fired when</th></tr></thead><tbody><tr><td><code>commitment.detected</code></td><td>Commitment first extracted</td></tr><tr><td><code>commitment.open</code></td><td>Moved to OPEN after review</td></tr><tr><td><code>commitment.due</code></td><td>Deadline reached</td></tr><tr><td><code>commitment.overdue</code></td><td>Past deadline, still open</td></tr><tr><td><code>commitment.fulfilled</code></td><td>Marked fulfilled</td></tr><tr><td><code>commitment.failed</code></td><td>Marked failed</td></tr><tr><td><code>commitment.cancelled</code></td><td>Cancelled</td></tr><tr><td><code>commitment.contradicted</code></td><td>Prior fulfillment contradicted</td></tr></tbody></table><p>See <a href="/core-concepts/webhooks.html">Webhooks</a> for payload format and signature verification.</p>`,21)])])}const E=t(n,[["render",i]]);export{m as __pageData,E as default};
